CREATE TABLE IF NOT EXISTS weather_forecasts (forecast_at DATETIME(6) PRIMARY KEY, location VARCHAR(80) NOT NULL, temperature_c DECIMAL(5,2) NOT NULL, cloud_pct DECIMAL(5,2) NOT NULL, precipitation_mm DECIMAL(8,2) NOT NULL, symbol_code VARCHAR(80) NOT NULL, solar_score DECIMAL(5,2) NOT NULL, expected_pv_w INT NOT NULL, source VARCHAR(40) NOT NULL, fetched_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS consumption_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_type VARCHAR(40) NOT NULL, started_at DATETIME(6) NOT NULL, ended_at DATETIME(6) NULL, baseline_w INT NOT NULL, detected_load_w INT NOT NULL, energy_kwh DECIMAL(10,3) NULL, confidence DECIMAL(4,3) NOT NULL, details_json JSON NOT NULL, INDEX idx_consumption_event_time(started_at));
